def page(s):
    nn=f"{s['n']:02d}"; fn=f"contracts/{s['sub']}/session-{nn}-{s['slug']}.sol"
    L=[f"# Session {s['n']} — {s['title']}",""]
    L+=["| Field | Value |","|---|---|",f"| Category | {s['cat']} |",f"| Source file | `{fn}` |",f"| Original root file | `{s['root']}` |",
        f"| Solidity | `{s['pragma']}` |",f"| Length | {s['lines']} lines |",f"| Structural family | {s['family']} |",
        f"| Threat classes | {s['tags']} ([taxonomy](../reference/taxonomy.md)) |",f"| Severity | **{s['sev']}** |",""]
    L+=["## Summary","",s['summary'],"","## How it works",""]+[f"- {m}" for m in s['mech']]
    L+=["","## Transfer predicate","",s['pred'],"","## Equations","",s['eq'],"","## Detection signals",""]+[f"- {d}" for d in s['detect']]
    L+=["","## Hard-coded addresses","",]
    if s['family']=="Clean": L+=["None.",""]
    else:
        extra = f", {D} (**D**)" if s['n'] in (6,7,8,9) else ""
        L+=[f"{A} (**A**), {B} (**B**), {C} (**C**){extra}, and the runtime-assembled {P} (**P**). Full table: [control-plane analysis](../analysis/control-plane.md#11-privileged-addresses-written-as-decimal-integers).",""]
    L+=["## Review guidance","","Reproduce findings on a local fork only. Use the [detection playbook](../guides/detection-playbook.md); do not trust the file name, labels or comments as evidence of behaviour.","",
        "> Documented for defensive analysis and education. Do not deploy this code or present it as safe.",""]
    return nn,"\n".join(L)
OUT.mkdir(parents=True,exist_ok=True)
for s in S:
    nn,t=page(s); (OUT/f"session-{nn}-{s['slug']}.md").write_text(t,encoding="utf8")
print("generated",len(S))
